-- GENERATED by supabase/scripts/generate-seed.mjs from src/data/challenges.json.
-- Do not edit by hand; run `npm run seed:generate`. Safe to re-run (upsert on id).
-- 30 approved challenges.

insert into public.challenges
  (id, track, kind, difficulty, prompt, options, correct_option_id, explanation, court,
   source_name, source_url, approved, coach_review_required)
values
  ('challenger-01', 'challenger', 'court-position', 1, 'The ball marker sits on the line that runs across your half of the court, about halfway between the net and your baseline. What is this line called?', '[{"id":"a","label":"Baseline"},{"id":"b","label":"Service line"},{"id":"c","label":"Center service line"},{"id":"d","label":"Singles sideline"}]'::jsonb, 'b', 'The service line marks the back of the service boxes, about halfway between the net and the baseline. The baseline is the line at the very back of the court.', '{"player":{"x":50,"y":97},"opponent":{"x":50,"y":3},"ball":{"x":50,"y":67.9},"caption":"You stand behind your baseline at the bottom of the court. The ball marker sits in the middle of the line that crosses your half of the court, about halfway between the net and your baseline."}'::jsonb, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, true),
  ('challenger-02', 'challenger', 'court-position', 1, 'After a rally shot, you are standing between your service line and your baseline. Why do coaches advise against staying there while your opponent hits?', '[{"id":"a","label":"Deep balls tend to bounce near your feet there, making clean shots hard"},{"id":"b","label":"The rules do not allow you to stand there during a rally"},{"id":"c","label":"You are not allowed to volley from there"},{"id":"d","label":"Lobs can only land in that area"}]'::jsonb, 'a', 'In this middle zone a deep ball often bounces at your feet, so you are forced into a half-volley or a rushed shot. Moving forward to the net or back behind the baseline gives you a clearer ball to hit.', '{"player":{"x":50,"y":81},"opponent":{"x":50,"y":4},"caption":"You are in the middle of your half, between your service line and your baseline. Your opponent is behind the far baseline, about to hit."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-03', 'challenger', 'court-position', 2, 'You just hit a deep crosscourt shot from near your right sideline. Your opponent will hit from behind their baseline on the left side of the diagram and could go anywhere. Where should you recover?', '[{"id":"a","label":"Exactly on the center mark"},{"id":"b","label":"Stay near your right sideline, where you hit from"},{"id":"c","label":"A little right of the center mark, just behind your baseline"},{"id":"d","label":"Forward to the middle of your service line"}]'::jsonb, 'c', 'Your opponent''s sharpest crosscourt angle is wider than their down-the-line option, so the middle of their possible shots is a little to the crosscourt side of the center mark. Exact center is close but leaves that wide angle more open, and staying out wide leaves the down-the-line side open.', '{"player":{"x":76,"y":96},"opponent":{"x":22,"y":6},"recommendedPath":[{"x":76,"y":96},{"x":57,"y":96}],"caption":"You are behind your baseline near the right sideline after hitting crosscourt. Your opponent is behind the far baseline on the left side of the diagram, about to reply."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-04', 'challenger', 'court-position', 2, 'You are rallying from your baseline near the right sideline. Why is a crosscourt shot toward the far left corner usually safer than going down the line?', '[{"id":"a","label":"In singles, crosscourt shots may land in the doubles alley"},{"id":"b","label":"The net is highest in the middle, which stops the ball going long"},{"id":"c","label":"Crosscourt shots always bounce higher"},{"id":"d","label":"It crosses the lower middle of the net and has a longer diagonal court to land in"}]'::jsonb, 'd', 'The net is lowest at the center (0.914 m) and higher at the posts, and the diagonal is longer than the sideline. A crosscourt ball therefore has more room for error both over the net and in length.', '{"player":{"x":78,"y":95},"opponent":{"x":50,"y":5},"recommendedPath":[{"x":78,"y":93},{"x":24,"y":12}],"caption":"You are behind your baseline near the right sideline. Your opponent is in the middle behind the far baseline. A diagonal toward the far left corner passes over the middle of the net."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-05', 'challenger', 'court-position', 3, 'You just hit down the line from near your right sideline, and your opponent will reply from the far right corner. Where should you recover?', '[{"id":"a","label":"Stay near your right sideline"},{"id":"b","label":"Move across to a little left of the center mark, just behind your baseline"},{"id":"c","label":"Go exactly to the center mark and stop"},{"id":"d","label":"Run to the left corner of your baseline"}]'::jsonb, 'b', 'From the far right corner, your opponent''s sharpest crosscourt angle goes toward your left side, so the middle of their options is slightly left of center. Going down the line means a longer recovery run, which is a trade-off of changing direction.', '{"player":{"x":80,"y":96},"opponent":{"x":78,"y":6},"recommendedPath":[{"x":80,"y":96},{"x":43,"y":96}],"caption":"You are behind your baseline near the right sideline after hitting down the line. Your opponent is behind the far baseline near the right side of the diagram, directly up the court from you."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-06', 'challenger', 'court-position', 1, 'In a baseline rally against an opponent who hits deep with medium pace, where is a good default spot to wait between shots?', '[{"id":"a","label":"About a step behind the baseline, near the middle"},{"id":"b","label":"On your service line"},{"id":"c","label":"Two steps inside your baseline"},{"id":"d","label":"Far back, close to the back fence"}]'::jsonb, 'a', 'About a step behind the baseline gives you time against deep balls while still letting you move forward to short ones. Standing much further back buys more time but opens angles and means more running.', '{"player":{"x":50,"y":88},"opponent":{"x":50,"y":3},"caption":"You are near the middle of your half of the court. Your opponent is rallying from behind the far baseline in the middle."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-07', 'challenger', 'court-position', 2, 'You have moved forward to the net to volley. Where is a good default position?', '[{"id":"a","label":"Right against the net, almost touching it"},{"id":"b","label":"On your service line"},{"id":"c","label":"Between your service line and your baseline"},{"id":"d","label":"Roughly halfway between your service line and the net"}]'::jsonb, 'd', 'Halfway between the service line and the net lets you cut off most passing shots while still having time to react and cover a lob. Very close to the net is easy to lob over, and the service line leaves many volleys low at your feet.', '{"player":{"x":50,"y":69},"opponent":{"x":50,"y":4},"caption":"You have just moved forward past your service line toward the net. Your opponent is behind the far baseline in the middle."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-08', 'challenger', 'court-position', 1, 'In a doubles rally (not the serve), the ball lands in the alley between the singles and doubles sidelines on your side. Is it in or out?', '[{"id":"a","label":"Out, because the alley is only used in singles"},{"id":"b","label":"Out, unless the ball touches the singles sideline"},{"id":"c","label":"In, because the alleys are part of the doubles court during rallies"},{"id":"d","label":"Neither: the point is replayed"}]'::jsonb, 'c', 'After the serve, the doubles court runs out to the doubles sidelines and includes both alleys. A ball landing in the alley during a doubles rally is good.', '{"player":{"x":40,"y":90},"opponent":{"x":60,"y":8},"ball":{"x":89,"y":80},"caption":"Doubles rally. You are near your baseline. The ball bounces in the narrow strip along the right edge of your half, outside the singles sideline but inside the outer doubles sideline."}'::jsonb, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, true),
  ('challenger-09', 'challenger', 'court-position', 2, 'In doubles, your serve lands in the alley right next to the correct service box. What is the call?', '[{"id":"a","label":"Fault, because the service box ends at the singles sideline"},{"id":"b","label":"Good, because the alleys count in doubles"},{"id":"c","label":"Let, so the serve is replayed"},{"id":"d","label":"Good, but only on a second serve"}]'::jsonb, 'a', 'The service boxes are the same in singles and doubles, and their outer edge is the singles sideline. A serve landing in the alley is a fault, even though the alley is in for the rest of the rally.', '{"player":{"x":58,"y":97},"opponent":{"x":25,"y":4},"ball":{"x":11.5,"y":42},"caption":"You serve from behind your baseline, just right of the center mark. The ball lands on the far side of the net on the left of the diagram, in the narrow alley just outside the left service box."}'::jsonb, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, true),
  ('challenger-10', 'challenger', 'court-position', 2, 'Doubles: your partner serves from the right half of your baseline. As the server''s partner, where do you usually start?', '[{"id":"a","label":"Next to your partner on the baseline"},{"id":"b","label":"In the right service box, directly in front of your partner"},{"id":"c","label":"On the center service line, touching the net"},{"id":"d","label":"In the left service box, roughly halfway between the net and the service line"}]'::jsonb, 'd', 'The traditional ''one up, one back'' start puts the server''s partner at the net on the opposite side from the server, guarding the alley and ready to intercept. Some teams choose other formations, such as both back, but this is the standard starting point.', null, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('rookie-01', 'rookie', 'rules', 1, 'A game has just started and you have won the first two points, so your score is 30. What is your score called if you also win the next point?', '[{"id":"a","label":"45"},{"id":"b","label":"40"},{"id":"c","label":"Game"},{"id":"d","label":"Advantage"}]'::jsonb, 'b', 'Point scores are called love, 15, 30 and 40, so a third point takes you to 40. You need one more point after 40 to win the game, unless the score reaches deuce.', null, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-02', 'rookie', 'rules', 1, 'The server has won two points and the receiver has won one. How should the score be called?', '[{"id":"a","label":"30–15"},{"id":"b","label":"15–30"},{"id":"c","label":"30–all"},{"id":"d","label":"40–15"}]'::jsonb, 'a', 'The server''s score is always called first. Two points is 30 and one point is 15, so the call is 30–15.', null, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-03', 'rookie', 'rules', 1, 'In a game with standard advantage scoring, both players have won three points. What is the score called?', '[{"id":"a","label":"40–30"},{"id":"b","label":"Advantage to the server"},{"id":"c","label":"Game to whoever won the most recent point"},{"id":"d","label":"Deuce"}]'::jsonb, 'd', 'Three points each is called deuce. From deuce, a player must win two points in a row to win the game.', null, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-04', 'rookie', 'rules', 2, 'At deuce, the receiver wins the next point. Then the server wins the point after that. What is the score now?', '[{"id":"a","label":"Game to the receiver"},{"id":"b","label":"Advantage to the server"},{"id":"c","label":"Deuce"},{"id":"d","label":"40–30 to the receiver"}]'::jsonb, 'c', 'Winning the point at deuce gives the receiver advantage. When the server wins the next point, that advantage is lost and the score returns to deuce.', null, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-05', 'rookie', 'rules', 1, 'Your first serve hits the net and lands outside the service box. Your second serve lands beyond the service line. What happens?', '[{"id":"a","label":"You get another first serve because the ball touched the net"},{"id":"b","label":"The point is replayed as a let"},{"id":"c","label":"You lose the point because of a double fault"},{"id":"d","label":"You serve again from the other half of the court"}]'::jsonb, 'c', 'A let only applies when a serve touches the net and then lands in the correct service box, so your first serve was a fault. Two faults in a row is a double fault, and the server loses the point.', null, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-06', 'rookie', 'rules', 1, 'You are serving the first point of a game from behind the baseline, just right of the center mark. Where must the serve land to be good?', '[{"id":"a","label":"In the service box straight ahead of you, on the same side of the court"},{"id":"b","label":"In the service box diagonally across the net from you"},{"id":"c","label":"Anywhere in your opponent''s singles court"},{"id":"d","label":"Anywhere between the opponent''s service line and baseline"}]'::jsonb, 'b', 'Each game starts with a serve from the right half of the court. The serve must land in the service box diagonally opposite, including its lines.', '{"player":{"x":55,"y":97},"opponent":{"x":30,"y":3},"caption":"You stand behind your baseline at the bottom of the court, just right of the center mark. The receiver waits behind the far baseline on the left side of the diagram, diagonally across from you."}'::jsonb, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-07', 'rookie', 'rules', 2, 'Your set uses standard rules: first to 6 games with a 2-game lead, and a tie-break at 6 games all. Which game score ends the set without a tie-break?', '[{"id":"a","label":"6–5"},{"id":"b","label":"5–3"},{"id":"c","label":"6–6"},{"id":"d","label":"7–5"}]'::jsonb, 'd', 'A set needs at least 6 games and a 2-game lead. At 6–5 play continues, so the set ends 7–5 or goes to a tie-break at 6–6.', null, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-08', 'rookie', 'rules', 2, 'In a tie-break, the score is 7–6. What happens next?', '[{"id":"a","label":"Play continues, because a player must lead by at least 2 points"},{"id":"b","label":"The player on 7 points wins the set"},{"id":"c","label":"One sudden-death point decides the set"},{"id":"d","label":"The tie-break resets to 0–0"}]'::jsonb, 'a', 'A tie-break is won by the first player to reach 7 points with a 2-point lead. At 7–6 nobody has won yet, so play continues until someone leads by two, such as 8–6 or 10–8.', null, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-09', 'rookie', 'rules', 2, 'You serve the first point of a tie-break. Who serves points 2 and 3?', '[{"id":"a","label":"You serve both"},{"id":"b","label":"Your opponent serves both"},{"id":"c","label":"Your opponent serves point 2 and you serve point 3"},{"id":"d","label":"Whoever won point 1 serves both"}]'::jsonb, 'b', 'The first server serves one point, then the players take turns serving two points each. Your opponent serves points 2 and 3, you serve points 4 and 5, and so on.', null, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-10', 'rookie', 'rules', 3, 'During a tie-break, when do the players change ends?', '[{"id":"a","label":"Each time the server changes"},{"id":"b","label":"Only when the score reaches 6–6"},{"id":"c","label":"After every six points, and again when the tie-break ends"},{"id":"d","label":"They never change ends during a tie-break"}]'::jsonb, 'c', 'Players change ends after every six points of a tie-break, which keeps conditions such as sun and wind fair. They also change ends when the tie-break is over.', null, 'ITF Rules of Tennis (2025)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('strategist-01', 'strategist', 'shot-choice', 2, 'You are balanced in the middle of your court with a comfortable, mid-height ball. Your opponent has been pulled wide, outside the far sideline on the left side of the diagram. Which shot is the best default?', '[{"id":"a","label":"Back to the same corner to wrong-foot them"},{"id":"b","label":"A drop shot just over the net"},{"id":"c","label":"A firm shot into the open court on the right, aimed well inside the sideline"},{"id":"d","label":"A high lob over your opponent"}]'::jsonb, 'c', 'The open court makes your opponent run the farthest, and aiming well inside the line keeps your margin. Going behind them can wrong-foot a fast recoverer, but against a player still stranded wide the open court is the higher-percentage choice.', '{"player":{"x":50,"y":80},"opponent":{"x":10,"y":8},"ball":{"x":50,"y":78},"caption":"You are balanced in the middle of your half, between baseline and service line. Your opponent is far out wide beyond the far left sideline, near their baseline, leaving the right side of their court open."}'::jsonb, 'USTA Player Development: Improve (tactical concepts, paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-02', 'strategist', 'shot-choice', 2, 'Your opponent has drifted far behind their baseline in the middle. You are inside your baseline on a short, slow, mid-height ball, and conditions are calm. Which shot is the best choice?', '[{"id":"a","label":"A drop shot that bounces soon after crossing the net"},{"id":"b","label":"A hard, flat shot straight at your opponent"},{"id":"c","label":"A high lob deep to their baseline"},{"id":"d","label":"A slow, deep rally ball back to the middle"}]'::jsonb, 'a', 'Your opponent has the longest possible run to the net, and from inside the court your drop shot only travels a short distance. A deep approach shot is also reasonable, but the drop shot best exploits their position.', '{"player":{"x":55,"y":72},"opponent":{"x":50,"y":2},"caption":"You are just behind your service line, near the middle of your half. Your opponent is far behind the far baseline, in the middle."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('strategist-03', 'strategist', 'shot-choice', 2, 'A deep, heavy ball has pushed you far behind your baseline near the left corner. Your opponent is on their baseline. Which reply is the safest default?', '[{"id":"a","label":"A drop shot from where you are"},{"id":"b","label":"A flat, low winner down the line"},{"id":"c","label":"A sharp, short angle crosscourt"},{"id":"d","label":"A high, deep crosscourt ball with plenty of net clearance"}]'::jsonb, 'd', 'From deep and off balance, a high crosscourt ball gives you the most margin and time to recover. A drop shot from far back travels too long and usually sits up for your opponent.', '{"player":{"x":22,"y":98},"opponent":{"x":50,"y":5},"caption":"You are far behind your baseline near the left corner. Your opponent is on the far baseline in the middle."}'::jsonb, 'USTA Player Development: Improve (tactical concepts, paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-04', 'strategist', 'shot-choice', 2, 'In a neutral rally with both players on the baseline, which target gives the best balance of pressure and safety?', '[{"id":"a","label":"Right on the sidelines and baseline, for maximum pressure"},{"id":"b","label":"Deep, a metre or two inside the lines, with comfortable net clearance"},{"id":"c","label":"Just over the net, as low as possible"},{"id":"d","label":"Into the service boxes"}]'::jsonb, 'b', 'Aiming a little inside the lines and well over the net leaves room for small errors while still keeping your opponent deep. Line-hugging targets win some points outright but cost more errors over a match.', '{"player":{"x":50,"y":96},"opponent":{"x":50,"y":4},"caption":"Both players are rallying from behind their baselines, in the middle of the court. Neither player is under pressure."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('strategist-05', 'strategist', 'shot-choice', 2, 'You get a short, mid-height ball on the right side of your court, just inside the service line. Your opponent is behind their baseline in the middle. You decide to come to the net. Where should you hit the approach shot?', '[{"id":"a","label":"Crosscourt to the far left corner"},{"id":"b","label":"Short and soft to the middle"},{"id":"c","label":"Deep down the line toward the far right corner, then follow it in"},{"id":"d","label":"A lob over your opponent"}]'::jsonb, 'c', 'A down-the-line approach reaches your opponent sooner and lets you follow the ball to cover their likely passing lanes. A crosscourt approach can work, but it leaves the down-the-line pass open behind you.', '{"player":{"x":72,"y":66},"opponent":{"x":50,"y":4},"ball":{"x":72,"y":64},"recommendedPath":[{"x":72,"y":64},{"x":78,"y":10}],"caption":"You are on the right side of your half, just inside your service line, with the ball in front of you. Your opponent is behind the far baseline in the middle."}'::jsonb, 'USTA Player Development: Improve (tactical concepts, paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-06', 'strategist', 'shot-choice', 2, 'Your deep approach has pushed your opponent into the far right corner, and they float a slow, high reply toward the middle. You are balanced at the net. Which volley is best?', '[{"id":"a","label":"A firm volley into the open court on the far left, away from your opponent"},{"id":"b","label":"A volley back to your opponent''s corner"},{"id":"c","label":"Let it bounce and rally from the baseline"},{"id":"d","label":"A lob volley over your opponent"}]'::jsonb, 'a', 'A floating reply gives you time to place the volley where your opponent is not. Volleying back to their corner gives them a second chance to pass you.', '{"player":{"x":62,"y":60},"opponent":{"x":80,"y":4},"ball":{"x":58,"y":58},"caption":"You are at the net, a little right of center. A slow, high ball is floating toward you. Your opponent is deep in the far right corner, leaving the far left side open."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('strategist-07', 'strategist', 'shot-choice', 2, 'Your opponent is close to the net in the middle. You are stretched wide behind your baseline near the right sideline, hitting on the run. Which shot is the best default?', '[{"id":"a","label":"A hard, flat passing shot down the line"},{"id":"b","label":"A high, deep defensive lob over your opponent"},{"id":"c","label":"A soft drop shot"},{"id":"d","label":"A hard shot straight at the net player"}]'::jsonb, 'b', 'When you are stretched, a high, deep lob buys time to recover and forces the net player to turn and chase. A passing shot is possible when you are balanced, but on the run it is a low-percentage choice.', '{"player":{"x":93,"y":97},"opponent":{"x":50,"y":40},"caption":"You are outside the right sideline behind your baseline, running wide. Your opponent is close to the net in the middle of the far half."}'::jsonb, 'USTA Player Development: Improve (tactical concepts, paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-08', 'strategist', 'shot-choice', 3, 'You have been rallying crosscourt from the left side of your court, and your opponent is waiting in the far right corner. Now you get a short, comfortable ball inside your baseline. What is a sensible choice?', '[{"id":"a","label":"Keep rallying crosscourt at the same pace"},{"id":"b","label":"A high defensive lob"},{"id":"c","label":"A sharp short angle into the area your opponent is covering"},{"id":"d","label":"Change direction down the line, toward the open far left corner"}]'::jsonb, 'd', 'Changing direction down the line works best on a short, comfortable ball, because the line shot crosses the higher part of the net and has less court to land in. Here you have that ball and an open court, so it is a good moment to switch; on a deep or difficult ball, staying crosscourt would be safer.', '{"player":{"x":28,"y":86},"opponent":{"x":72,"y":6},"ball":{"x":28,"y":84},"caption":"You are inside your baseline on the left side of your half, with a short ball in front of you. Your opponent is behind the far baseline on the right side of the diagram, leaving the far left corner open."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('strategist-09', 'strategist', 'shot-choice', 3, 'Your opponent has come forward and is standing near their service line. You are balanced just behind your baseline with a low ball below net height. Which shot is the best default?', '[{"id":"a","label":"A high, deep lob"},{"id":"b","label":"A hard, rising shot aimed at their chest"},{"id":"c","label":"A dipping shot that drops low at their feet or past them"},{"id":"d","label":"A drop shot"}]'::jsonb, 'c', 'An opponent near the service line is vulnerable to a ball that dips at their feet, forcing an upward volley. A lob is a reasonable alternative, especially if they move closer to the net.', '{"player":{"x":50,"y":93},"opponent":{"x":50,"y":30},"caption":"You are just behind your baseline in the middle. Your opponent has moved forward and is standing near the far service line, in the middle."}'::jsonb, 'USTA Player Development: Improve (tactical concepts, paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-10', 'strategist', 'shot-choice', 2, 'Assume you know your opponent''s backhand is clearly weaker than their forehand, and the rally is neutral. Which plan best builds the point?', '[{"id":"a","label":"Keep hitting deep, steady balls to the backhand until you get a short ball to attack"},{"id":"b","label":"Go for an outright winner on the first ball"},{"id":"c","label":"Hit everything to the forehand to tire them out"},{"id":"d","label":"Hit every shot to a new corner as hard as possible"}]'::jsonb, 'a', 'Steady pressure on the weaker side tends to draw a short or defensive reply that you can then attack. An occasional ball to the forehand still helps open the court, but the backhand is the main target.', null, 'USTA Player Development: Improve (tactical concepts, paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true)
on conflict (id) do update set
  track = excluded.track,
  kind = excluded.kind,
  difficulty = excluded.difficulty,
  prompt = excluded.prompt,
  options = excluded.options,
  correct_option_id = excluded.correct_option_id,
  explanation = excluded.explanation,
  court = excluded.court,
  source_name = excluded.source_name,
  source_url = excluded.source_url,
  approved = excluded.approved,
  coach_review_required = excluded.coach_review_required;
